/** Synthetic bank-style payload: acquirer template (26: 02=terminal id) + switching template (51: 02=NMID). */
export function syntheticBankNeo(): string {
  const body =
    "000201010211" +
    "26740025ID.CO.BANKNEOCOMMERCE.WWW011893600490594025501202120005900565650303UMI" +
    "51550025ID.CO.BANKNEOCOMMERCE.WWW0215ID10232469899990303UMI" +
    "5204541153033605802ID5910DHKA STORE6013BANDUNG BARAT6105403916233052230016985445676624117760703T01" +
    "6304";
  return body + calculateCRC16(body);
}
